     const match=cell.match(/<v(?:\s[^>]*)?>([\s\S]*?)<\/v>/),value=match?match[1].trim():'';
     if(value&&Number.isFinite(new Date(value).getTime()))return cell;
     repairedDates++;changed=true;if(!value||/^(?:null|undefined)$/i.test(value))return '';
